package sohal.lld.chess;import sohal.lld.chess.entity.Color;import sohal.lld.chess.entity.board.Board;import sohal.lld.chess.entity.board.Move;import sohal.lld.chess.entity.playable.Piece;import sohal.lld.chess.exception.InvalidMoveException;import sohal.lld.chess.player.Player;import java.util.Scanner;public class ChessGame {    Board board;    Player whitePlayer;    Player blackPlayer;    Player currentPlayer;    public ChessGame() {        this.board = new Board();    }    void setPlayers(String whitePlayerName, String blackPlayerName) {        this.whitePlayer = new Player(whitePlayerName, Color.WHITE);        this.blackPlayer = new Player(blackPlayerName, Color.BLACK);        this.currentPlayer = this.whitePlayer;    }    void start() {        while(!isGameOver()) {            Player player = this.currentPlayer;            System.out.println(player + "'s turn");            Move move = getCurrentMove(player);            try {                board.movePiece(move);                board.printBoard();            } catch (InvalidMoveException e) {                System.out.println(e.getMessage());                System.out.println("Invalid move, try again");                continue;            }            switchTurns();        }        displayResult();    }    void switchTurns() {        currentPlayer = currentPlayer ==  blackPlayer ? whitePlayer : blackPlayer;    }    boolean isGameOver() {        return board.isCheckMate(whitePlayer.getColor()) ||  board.isCheckMate(blackPlayer.getColor())                || board.isStaleMate(whitePlayer.getColor()) || board.isStaleMate(blackPlayer.getColor());    }    private Move getCurrentMove(Player player) {        Scanner input = new Scanner(System.in);        System.out.print("Enter source row: ");        int sourceRow = input.nextInt();        System.out.print("Enter source column: ");        int sourceCol = input.nextInt();        System.out.print("Enter destination row: ");        int destRow = input.nextInt();        System.out.print("Enter destination column: ");        int destCol = input.nextInt();        Piece piece = board.getPiece(sourceRow, sourceCol);        if(piece == null || piece.getColor() != player.getColor()) {            System.out.println("Invalid move, try again");        }        return new Move(board.getCell(sourceRow, sourceCol), board.getCell(destRow, destCol));    }    private void displayResult() {        if (board.isCheckMate(Color.WHITE)) {            System.out.println("Black wins by checkmate!");        } else if (board.isCheckMate(Color.BLACK)) {            System.out.println("White wins by checkmate!");        } else if (board.isStaleMate(Color.WHITE) || board.isStaleMate(Color.BLACK)) {            System.out.println("The game ends in a stalemate!");        }    }}